"use client";

import { useMemo, useState } from "react";
import { Filter, ChevronDown, ChevronUp, Check, RotateCcw } from "lucide-react";
import { formatVND } from "@/lib/utils";

export interface PriceRangeValue {
  min: number;
  max: number;
}

export type SortOption = "featured" | "price-asc" | "price-desc" | "name-asc";

export interface ProductFilters {
  priceRange: PriceRangeValue;
  bestSellerOnly: boolean;
  sort: SortOption;
}

interface ProductFilterSidebarProps {
  filters: ProductFilters;
  onChange: (filters: ProductFilters) => void;
}

export const PRICE_RANGE_LIMITS: PriceRangeValue = {
  min: 0,
  max: 10000000,
};

const PRICE_STEP = 100000;

const SORT_OPTIONS: { id: SortOption; label: string }[] = [
  { id: "featured", label: "Nổi bật" },
  { id: "price-asc", label: "Giá thấp đến cao" },
  { id: "price-desc", label: "Giá cao đến thấp" },
  { id: "name-asc", label: "Tên A-Z" },
];

export const defaultProductFilters: ProductFilters = {
  priceRange: { ...PRICE_RANGE_LIMITS },
  bestSellerOnly: false,
  sort: "featured",
};

export default function ProductFilterSidebar({
  filters,
  onChange,
}: ProductFilterSidebarProps) {
  const [openSections, setOpenSections] = useState({
    price: true,
    status: true,
    sort: true,
  });

  const priceRangeChanged =
    filters.priceRange.min !== PRICE_RANGE_LIMITS.min ||
    filters.priceRange.max !== PRICE_RANGE_LIMITS.max;

  const activeCount = useMemo(
    () => (priceRangeChanged ? 1 : 0) + (filters.bestSellerOnly ? 1 : 0),
    [filters.bestSellerOnly, priceRangeChanged]
  );

  const minPercent =
    ((filters.priceRange.min - PRICE_RANGE_LIMITS.min) /
      (PRICE_RANGE_LIMITS.max - PRICE_RANGE_LIMITS.min)) *
    100;
  const maxPercent =
    ((filters.priceRange.max - PRICE_RANGE_LIMITS.min) /
      (PRICE_RANGE_LIMITS.max - PRICE_RANGE_LIMITS.min)) *
    100;

  const toggleSection = (section: keyof typeof openSections) => {
    setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const updatePriceRange = (priceRange: PriceRangeValue) => {
    onChange({ ...filters, priceRange });
  };

  const clearFilters = () => {
    onChange({
      ...defaultProductFilters,
      priceRange: { ...PRICE_RANGE_LIMITS },
    });
  };

  return (
    <div className="w-full bg-card rounded-xl border border-border p-5 shadow-sm sticky top-24">
      <div className="flex items-start justify-between gap-3 mb-6 pb-4 border-b border-border">
        <div className="flex items-center gap-2">
          <Filter className="w-5 h-5 text-primary" />
          <div>
            <h2 className="text-lg font-semibold text-foreground">Bộ lọc sản phẩm</h2>
            <p className="text-xs text-muted-foreground">
              {activeCount > 0 ? `${activeCount} bộ lọc đang bật` : "Lọc theo nhu cầu mua sắm"}
            </p>
          </div>
        </div>
        {activeCount > 0 && (
          <button
            type="button"
            onClick={clearFilters}
            className="rounded-full p-2 text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
            aria-label="Xóa bộ lọc"
          >
            <RotateCcw className="h-4 w-4" />
          </button>
        )}
      </div>

      <div className="mb-6 border-b border-border pb-6">
        <div
          className="flex items-center justify-between mb-3 cursor-pointer group"
          onClick={() => toggleSection("price")}
        >
          <h3 className="font-medium text-foreground group-hover:text-primary transition-colors">Khoảng Giá</h3>
          {openSections.price ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
        </div>

        {openSections.price && (
          <div className="space-y-4 animate-in slide-in-from-top-2 fade-in duration-200">
            <div className="grid grid-cols-2 gap-3">
              <div className="rounded-lg border border-border bg-muted/40 px-3 py-2">
                <p className="text-xs text-muted-foreground">Từ</p>
                <p className="mt-1 text-sm font-semibold text-foreground">
                  {formatVND(filters.priceRange.min)}
                </p>
              </div>
              <div className="rounded-lg border border-border bg-muted/40 px-3 py-2 text-right">
                <p className="text-xs text-muted-foreground">Đến</p>
                <p className="mt-1 text-sm font-semibold text-foreground">
                  {formatVND(filters.priceRange.max)}
                </p>
              </div>
            </div>

            <div className="px-1 pt-2">
              <div className="relative h-8">
                <div className="absolute top-1/2 h-2 w-full -translate-y-1/2 rounded-full bg-secondary" />
                <div
                  className="absolute top-1/2 h-2 -translate-y-1/2 rounded-full bg-primary"
                  style={{
                    left: `${minPercent}%`,
                    right: `${100 - maxPercent}%`,
                  }}
                />
                <input
                  type="range"
                  min={PRICE_RANGE_LIMITS.min}
                  max={PRICE_RANGE_LIMITS.max}
                  step={PRICE_STEP}
                  value={filters.priceRange.min}
                  onChange={(event) =>
                    updatePriceRange({
                      ...filters.priceRange,
                      min: Math.min(
                        Number(event.target.value),
                        filters.priceRange.max - PRICE_STEP
                      ),
                    })
                  }
                  className="price-range-input z-30"
                  aria-label="Giá thấp nhất"
                />
                <input
                  type="range"
                  min={PRICE_RANGE_LIMITS.min}
                  max={PRICE_RANGE_LIMITS.max}
                  step={PRICE_STEP}
                  value={filters.priceRange.max}
                  onChange={(event) =>
                    updatePriceRange({
                      ...filters.priceRange,
                      max: Math.max(
                        Number(event.target.value),
                        filters.priceRange.min + PRICE_STEP
                      ),
                    })
                  }
                  className="price-range-input z-20"
                  aria-label="Giá cao nhất"
                />
              </div>

              <div className="mt-2 flex items-center justify-between text-xs text-muted-foreground">
                <span>{formatVND(PRICE_RANGE_LIMITS.min)}</span>
                <span>{formatVND(PRICE_RANGE_LIMITS.max)}</span>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mb-6 border-b border-border pb-6">
        <div
          className="flex items-center justify-between mb-3 cursor-pointer group"
          onClick={() => toggleSection("status")}
        >
          <h3 className="font-medium text-foreground group-hover:text-primary transition-colors">Trạng thái</h3>
          {openSections.status ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
        </div>

        {openSections.status && (
          <button
            type="button"
            onClick={() => onChange({ ...filters, bestSellerOnly: !filters.bestSellerOnly })}
            className="flex w-full items-center gap-3 cursor-pointer group text-left animate-in slide-in-from-top-2 fade-in duration-200"
          >
            <div className={`relative flex items-center justify-center w-4 h-4 border rounded-sm transition-colors ${filters.bestSellerOnly ? 'border-primary bg-primary' : 'border-input group-hover:border-primary'}`}>
              {filters.bestSellerOnly && <Check className="w-3 h-3 text-primary-foreground absolute" />}
            </div>
            <span className={`text-sm transition-colors ${filters.bestSellerOnly ? 'text-foreground font-medium' : 'text-muted-foreground group-hover:text-foreground'}`}>
              Chỉ hiển thị sản phẩm bán chạy
            </span>
          </button>
        )}
      </div>

      <div className="mb-6">
        <div
          className="flex items-center justify-between mb-3 cursor-pointer group"
          onClick={() => toggleSection("sort")}
        >
          <h3 className="font-medium text-foreground group-hover:text-primary transition-colors">Sắp xếp</h3>
          {openSections.sort ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
        </div>
        
        {openSections.sort && (
          <div className="space-y-2.5 animate-in slide-in-from-top-2 fade-in duration-200">
            {SORT_OPTIONS.map((option) => {
              const isSelected = filters.sort === option.id;
              return (
                <button
                  key={option.id}
                  type="button"
                  className="flex w-full items-center gap-3 cursor-pointer group text-left"
                  onClick={() => onChange({ ...filters, sort: option.id })}
                >
                  <div className={`relative flex items-center justify-center w-4 h-4 rounded-full border transition-colors ${isSelected ? 'border-primary' : 'border-input group-hover:border-primary'}`}>
                    {isSelected && <div className="h-2 w-2 rounded-full bg-primary" />}
                  </div>
                  <span className={`text-sm transition-colors ${isSelected ? 'text-foreground font-medium' : 'text-muted-foreground group-hover:text-foreground'}`}>
                    {option.label}
                  </span>
                </button>
              );
            })}
          </div>
        )}
      </div>
      <button 
        type="button"
        onClick={clearFilters}
        className="w-full py-2.5 mt-2 text-sm text-muted-foreground hover:text-foreground hover:bg-muted rounded-md transition-colors"
      >
        Xóa bộ lọc
      </button>
    </div>
  );
}
