"use client";

import { useMemo, useState } from "react";
import CategoryProductGrid from "@/components/category/CategoryProductGrid";
import ProductFilterSidebar, {
  defaultProductFilters,
  ProductFilters,
} from "@/components/category/ProductFilterSidebar";
import { Product } from "@/types/product";
import Link from "next/link";
import { SearchX } from "lucide-react";

interface CategoryProductBrowserProps {
  products: Product[];
  categoryName: string;
}

export default function CategoryProductBrowser({
  products,
  categoryName,
}: CategoryProductBrowserProps) {
  const [filters, setFilters] = useState<ProductFilters>(defaultProductFilters);

  const filteredProducts = useMemo(() => {
    const nextProducts = products.filter((product) => {
      const matchesPrice =
        product.price >= filters.priceRange.min &&
        product.price <= filters.priceRange.max;
      const matchesStatus = !filters.bestSellerOnly || product.isBestSeller;

      return matchesPrice && matchesStatus;
    });

    return [...nextProducts].sort((a, b) => {
      if (filters.sort === "price-asc") return a.price - b.price;
      if (filters.sort === "price-desc") return b.price - a.price;
      if (filters.sort === "name-asc") return a.name.localeCompare(b.name, "vi");
      return Number(Boolean(b.isBestSeller)) - Number(Boolean(a.isBestSeller));
    });
  }, [filters, products]);

  return (
    <div className="flex flex-col lg:flex-row gap-8 mt-8">
      <div className="w-full lg:w-1/4 flex-shrink-0">
        <ProductFilterSidebar filters={filters} onChange={setFilters} />
      </div>

      <div className="w-full lg:w-3/4">
        <div className="mb-5 flex items-center justify-between gap-4">
          <p className="text-sm text-muted-foreground">
            Hiển thị <span className="font-semibold text-foreground">{filteredProducts.length}</span> / {products.length} sản phẩm
          </p>
        </div>

        {filteredProducts.length > 0 ? (
          <CategoryProductGrid products={filteredProducts} />
        ) : (
          <div className="flex flex-col items-center justify-center py-20 text-center bg-card rounded-xl border border-border shadow-sm">
            <SearchX className="h-14 w-14 text-muted-foreground mb-5" />
            <h3 className="text-2xl font-semibold text-foreground mb-3">
              Không có sản phẩm phù hợp
            </h3>
            <p className="text-muted-foreground max-w-md mx-auto">
              Không có sản phẩm nào trong danh mục {categoryName} khớp với bộ lọc hiện tại.
            </p>
            <Link href="/" className="mt-6 px-6 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 transition-colors">
              Trở về trang chủ
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}
